// ============================================================
// TRACE — measuring a reference photograph
//
// THE RULE THIS FILE EXISTS TO ENFORCE: no shape in this project is ever
// generated by a formula over a bounding half-width. Every outline is an
// ordered list of CORNER PIXELS read off a specific photograph.
//
// Five earlier builds failed by recording a height, a half-width and a depth
// per part — a bounding box, which cannot describe a shape, only the box a
// shape fits in. The sixth failed differently and more subtly: its blueprint
// held real traced corners, but its geometry still generated cross-sections
// parametrically, `[-hw, b*0.62], [-hw*0.72, b], …`. Invented fractions of a
// bounding half-width are a bounding box wearing a trace's clothes.
//
// So a traced outline is a BRANDED TYPE here. `corners()` stamps the array
// with its source image and pixel list, and `poly.js` REFUSES an unbranded
// outline. Writing a parametric cross-section is not discouraged any more —
// it throws.
//
// MEASURE WITH A TOOL, NOT WITH YOUR EYES. Eyeballing a magnified crop was
// reliably ~20% out. `scripts/probe/crop.mjs` burns a labelled coordinate
// grid over an upscaled crop; you read the corner off the picture and its
// pixel coordinate off the grid in the same glance.
// ============================================================

const BRAND = Symbol.for('mechkit.traced');

/**
 * Stamps an outline as measured, recording where it came from.
 *
 * The provenance travels with the geometry all the way to `report()`, so any
 * plate on screen can be traced back to the crop that produced it.
 */
export function brand(pts, source) {
  Object.defineProperty(pts, BRAND, { value: source, enumerable: false });
  return pts;
}

export const provenance = (pts) => (pts && pts[BRAND]) || null;
export const isTraced = (pts) => Boolean(provenance(pts));

/**
 * Asserts an outline was measured. Called by every primitive that consumes
 * one, which is what makes "trace, don't invent" a property of the code
 * rather than a note in a comment.
 */
export function requireTraced(pts, who) {
  if (!isTraced(pts)) {
    throw new Error(
      `${who}: outline is not traced.\n` +
      'Every outline must come from elevation().corners() / .cornersZ() / .plan(),\n' +
      'or be a straight-edge derivation of one via derive(). A cross-section\n' +
      'generated from a bounding half-width is a bounding box — hard rule 1.',
    );
  }
  return pts;
}

/**
 * Carries provenance through a straight-edge transform.
 *
 *   derive(FRONT.corners(px), (o) => chamfer(mirrorX(o), 0.01))
 *
 * The point is not to make branding easy to satisfy — it is that a chamfer or
 * a mirror of a measured outline is still measured, while a polygon conjured
 * from a scalar is not, and the two must stay distinguishable.
 */
export function derive(pts, fn, note = 'derived') {
  const src = provenance(pts);
  if (!src) throw new Error('derive(): source outline is not traced');
  return brand(fn(pts), { ...src, note: src.note ? `${src.note} → ${note}` : note });
}

/**
 * Calibrates one reference elevation, in RAW IMAGE PIXELS.
 *
 * Raw pixels rather than normalized coordinates because that is what the
 * probe prints and what the gridded crop is labelled with: every number in a
 * blueprint can be pasted straight back into the tool that produced it, with
 * no division in between to get wrong.
 *
 *   crown    pixel row of the top of the region being calibrated
 *   sole     pixel row of its bottom
 *   midline  pixel column of the body centreline   (front / rear elevations)
 *   origin   pixel column of the suit's own z = 0  (side elevations)
 *   height   model units the crown→sole span represents
 *   w, h     the image's pixel size, so the overlay can frame it
 *   image    filename inside references/<unit>/
 *   note     what this shot can and cannot be trusted for
 */
export function elevation(cal) {
  const {
    crown, sole, midline = 0, origin = 0, height, w = 1, h = 1,
    image = null, note = null,
  } = cal;
  const span = sole - crown;
  const per = height / span;          // model units per pixel, both axes

  const src = (kind, pixels) => ({ image, kind, pixels, note });

  const api = {
    cal, image, w, h, note, per,
    /** pixel row → model Y, with 0 at `sole`. */
    y: (py) => (sole - py) * per,
    /** pixel row → fraction of the calibrated span. */
    frac: (py) => (sole - py) / span,
    /** pixel column → model X, signed from the midline (+ image-right). */
    x: (px) => (px - midline) * per,
    /** pixel column → half-width from the midline (always positive). */
    hw: (px) => Math.abs(px - midline) * per,
    /** pixel column → model Z on a SIDE elevation, + forward. */
    z: (px) => (px - origin) * per,
    /** a measured pixel distance → model units. */
    d: (px) => px * per,

    /**
     * A TRACED CORNER POLYGON → a model-space outline in XY.
     *
     * Wind it COUNTER-CLOCKWISE AS THE PART IS SEEN: start bottom-left, right
     * along the bottom, up the right side, left across the top, down the
     * left. Image rows increase downward, so this flips y for you — trace
     * what you see.
     */
    corners: (pixels) => brand(
      pixels.map(([px, py]) => [api.x(px), api.y(py)]), src('front', pixels),
    ),

    /** The same, drawn in a SIDE elevation → an outline in ZY. */
    cornersZ: (pixels) => brand(
      pixels.map(([px, py]) => [api.z(px), api.y(py)]), src('side', pixels),
    ),

    /**
     * A TRACED PLAN OUTLINE → a polygon in XZ, for `stack()`.
     *
     * `pixels` are read off a TOP-DOWN or high-angle shot: column → x,
     * row → z, with `zRow` the image row that is the part's z = 0.
     */
    plan: (pixels, zRow) => brand(
      pixels.map(([px, py]) => [api.x(px), (zRow - py) * per]), src('plan', pixels),
    ),

    /**
     * A traced polygon expressed in its OWN frame, sized 1 × 1 about its own
     * centre — for when a part's SHAPE is measured on one photograph and its
     * SIZE comes from another.
     */
    unit: (pixels) => {
      const b = pixels.reduce((a, [px, py]) => ({
        x0: Math.min(a.x0, px), x1: Math.max(a.x1, px),
        y0: Math.min(a.y0, py), y1: Math.max(a.y1, py),
      }), { x0: Infinity, x1: -Infinity, y0: Infinity, y1: -Infinity });
      const ww = (b.x1 - b.x0) || 1, hh = (b.y1 - b.y0) || 1;
      return brand(pixels.map(([px, py]) => [
        (px - (b.x0 + b.x1) / 2) / ww,
        ((b.y0 + b.y1) / 2 - py) / hh,
      ]), src('unit', pixels));
    },

    /** Named pixel rows → model heights. */
    heights: (marks) => map(marks, api.y),
    /** Named pixel columns → model half-widths. */
    widths: (marks) => map(marks, api.hw),
    /** Named pixel columns → signed model X. */
    columns: (marks) => map(marks, api.x),
    /** Named pixel columns → model depths (side elevation). */
    depths: (marks) => map(marks, api.z),
    /** Named measured pixel SPANS → model half-widths. Pose-proof. */
    spans: (marks) => map(marks, (px) => api.d(px / 2)),
  };
  return api;
}

const map = (marks, f) =>
  Object.fromEntries(Object.entries(marks).map(([k, v]) => [k, f(v)]));

/** Scales a unit-frame outline (from `elevation().unit`) to a real size. */
export const sized = (unitPts, w, h) =>
  derive(unitPts, (p) => p.map(([x, y]) => [x * w, y * h]), `sized ${w}×${h}`);

/**
 * Cross-checks two elevations of the same suit. They are the same machine, so
 * their model-units-per-pixel scales should describe the same height and the
 * ratio should be 1. If they disagree the suit comes out deep-but-narrow or
 * the reverse — which reads as "the proportions are off" and sends you tuning
 * armour that was correct.
 */
export const calibrationRatio = (a, b) => a.per / b.per;

/**
 * Asserts two elevations agree, at module load, so a bad calibration is a
 * startup error rather than a shape someone spends a session tuning.
 */
export function assertCalibrated(a, b, tol = 0.06, label = '') {
  const r = calibrationRatio(a, b);
  if (Math.abs(r - 1) > tol) {
    throw new Error(
      `calibration mismatch ${label}: ${a.image} vs ${b.image} ratio ${r.toFixed(3)}`,
    );
  }
  return r;
}

/**
 * Solves a spar's far end from its TRACED TIP.
 *
 * NEVER author a length and an angle independently — both numbers look
 * plausible and the tip lands nowhere near the picture.
 */
export const spanTo = (root, tip) => ({
  root, tip,
  len: Math.hypot(tip[0] - root[0], tip[1] - root[1]),
  angle: Math.atan2(tip[1] - root[1], tip[0] - root[0]),
});

/**
 * THE ONE ESCAPE HATCH, and it costs you a sentence.
 *
 * A few outlines genuinely have no photograph behind them: the hex section of
 * a piston rod, the octagon of a joint drum, the bolt circle on a pivot
 * block. Those are HARDWARE — machined stock that the brief specifies by
 * kind rather than the reference by shape.
 *
 * `why` is required and is not decoration: it is printed by `report()` next
 * to the part, so an outline that should have been measured and was not is
 * visible in the audit instead of hiding behind a brand.
 *
 * If you are reaching for this to describe an ARMOUR PLATE, you are about to
 * repeat the mistake this kit was rewritten to prevent. Go and trace it.
 */
export function hardware(pts, why) {
  if (!why) throw new Error('hardware(): every untraced outline must say why');
  return brand(pts, { image: null, kind: 'hardware', pixels: null, note: why });
}
